"use client";

import { ChangeEvent, FormEvent, useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { Activity, BarChart3, Bell, BookOpen, Bot, CalendarDays, Check, ChevronDown, CircleHelp, CreditCard, FileText, Image as ImageIcon, Languages, LayoutDashboard, LogOut, Menu, MessageCircle, PanelLeftClose, PanelLeftOpen, Pause, Play, Plug, Plus, Search, Send, Settings, Sparkles, TestTube2, Upload, UserRoundPlus, WandSparkles, X, Zap } from "lucide-react";
import { Logo } from "./logo";
import { logout } from "@/app/actions/auth";
import { createTranslator, dateLocale, type MessageKey } from "@/lib/i18n";
import { employeeRoleLabel, employeeToneLabel } from "@/lib/employee-domain";

type PageId="overview"|"employees"|"conversations"|"leads"|"appointments"|"knowledge"|"actions"|"rules"|"channels"|"integrations"|"analytics"|"team"|"billing"|"settings"|"notifications"|"testing";
const pageLabels:Record<PageId,string>={overview:"Обзор",employees:"Сотрудники",conversations:"Диалоги",leads:"Лиды",appointments:"Записи",knowledge:"Знания",actions:"Действия",rules:"Правила",channels:"Каналы",integrations:"Интеграции",analytics:"Аналитика",team:"Команда",billing:"Тариф и использование",settings:"Настройки",notifications:"Уведомления",testing:"Тестирование"};
const pageByLabel=new Map(Object.entries(pageLabels).map(([id,label])=>[label,id as PageId]));
const sections=[
  {title:"group.main",items:[["overview",LayoutDashboard,"nav.overview"]]},
  {title:"group.ai",items:[["employees",Bot,"nav.employees"]]},
  {title:"group.work",items:[["conversations",MessageCircle,"nav.conversations"],["leads",UserRoundPlus,"nav.leads"],["appointments",CalendarDays,"nav.appointments"]]},
  {title:"group.setup",items:[["knowledge",BookOpen,"nav.knowledge"],["actions",Zap,"nav.actions"],["rules",CircleHelp,"nav.rules"]]},
  {title:"group.connections",items:[["channels",Plug,"nav.channels"],["integrations",WandSparkles,"nav.integrations"]]},
  {title:"group.results",items:[["analytics",BarChart3,"nav.analytics"]]},
  {title:"group.workspace",items:[["team",UserRoundPlus,"nav.team"],["billing",CreditCard,"nav.billing"]]},
] as const;

function Sparkline({ points }: { points: number[] }) {
  const coords = points.map((p, i) => `${i * 18},${44 - p / 2}`).join(" ");
  return <svg className="spark" viewBox="0 0 108 48" aria-hidden><polyline points={coords} /></svg>;
}

function PeriodDropdown({locale,value,options,onChange}:{locale:string;value:number;options:Array<{d:number;l:string}>;onChange:(value:number)=>void}){
  const [open,setOpen]=useState(false);const rootRef=useRef<HTMLDivElement>(null);const selected=options.find(option=>option.d===value)??options[0];
  useEffect(()=>{if(!open)return;const close=(event:MouseEvent)=>{if(!rootRef.current?.contains(event.target as Node))setOpen(false)};const escape=(event:KeyboardEvent)=>{if(event.key==="Escape")setOpen(false)};document.addEventListener("mousedown",close);window.addEventListener("keydown",escape);return()=>{document.removeEventListener("mousedown",close);window.removeEventListener("keydown",escape)}},[open]);
  return <div className="periodDropdown" ref={rootRef}><button type="button" className="periodTrigger" aria-haspopup="listbox" aria-expanded={open} onClick={()=>setOpen(value=>!value)}><span><small>{locale==="ru"?"Период":"Period"}</small><b>{selected.l}</b></span><span className="periodChevron"><ChevronDown size={16}/></span></button><div className="periodMenu" data-open={open} role="listbox" aria-label={locale==="ru"?"Выбор периода":"Select period"}>{options.map(option=><button type="button" role="option" aria-selected={option.d===value} className={option.d===value?"periodOption selected":"periodOption"} key={option.d} onClick={()=>{onChange(option.d);setOpen(false)}}><span>{option.l}</span>{option.d===value&&<Check size={15}/>}</button>)}</div></div>;
}

function sevenDaySeries(events: PlatformData["analyticsEvents"], type: string) {
  const today = new Date();
  return Array.from({ length: 7 }, (_, offset) => {
    const day = new Date(today);day.setHours(0,0,0,0);day.setDate(day.getDate()-(6-offset));const end=new Date(day);end.setDate(end.getDate()+1);
    return events.filter((event) => event.type === type && new Date(event.createdAt) >= day && new Date(event.createdAt) < end).length * 2;
  });
}

const auditRu:Record<string,string>={WORKSPACE_CREATED:"Создано рабочее пространство",WORKSPACE_SETTINGS_UPDATED:"Обновлены настройки пространства",AI_EMPLOYEE_CREATED:"Создан ИИ-сотрудник",AI_EMPLOYEE_PUBLISHED:"Опубликован ИИ-сотрудник",AI_EMPLOYEE_UPDATED:"Обновлён ИИ-сотрудник",EMPLOYEE_STATUS_CHANGED:"Изменён статус ИИ-сотрудника",ACTION_PERMISSION_CHANGED:"Изменены разрешения действий",KNOWLEDGE_SOURCE_CREATED:"Добавлен источник знаний",CHANNEL_CONFIGURED:"Настроен канал",CHANNEL_DISCONNECTED:"Отключён канал",INVITATION_CREATED:"Создано приглашение",INVITATION_ACCEPTED:"Принято приглашение",WORKSPACE_DATA_EXPORTED:"Экспортированы данные",RETENTION_ENFORCED:"Выполнена политика хранения данных",AUTOMATION_CREATED:"Создано правило автоматизации",AUTOMATION_TOGGLED:"Изменён статус автоматизации",WORK_ASSIGNED:"Назначен ответственный",WORK_UNASSIGNED:"Снят ответственный",CUSTOMER_DATA_DELETED:"Удалены данные клиента",CRM_INTEGRATION_CONFIGURED:"Настроена CRM-интеграция",MEMBER_INVITED:"Приглашён участник команды",MEMBER_ROLE_CHANGED:"Изменена роль участника",MEMBER_REMOVED:"Удалён участник команды"};
function auditLabel(value:string,locale:string){if(locale==="ru")return auditRu[value]??value.replaceAll("_"," ").toLocaleLowerCase("ru");return value.replaceAll("_"," ").toLocaleLowerCase("en")}
function entityLabel(value:string,locale:string){if(locale!=="ru")return value;return({Workspace:"Пространство",AIEmployee:"ИИ-сотрудник",Channel:"Канал",WorkspaceInvitation:"Приглашение",KnowledgeSource:"Источник знаний",Automation:"Автоматизация",Customer:"Клиент",Integration:"Интеграция",WorkspaceMember:"Участник команды",Conversation:"Диалог",Lead:"Лид"} as Record<string,string>)[value]??value}
function LemiriMark({className=""}:{className?:string}){return <img className={`lemiriMark ${className}`} src="/brand/lemiri-mark.png" alt="" aria-hidden="true"/>}
type Assignee={id:string;name:string}|null;
type PlatformData={employees:Array<{id:string;name:string;role:string;status:string;goal:string;tone:string;assignee:Assignee;permissions:Array<{key:string;enabled:boolean}>}>;sources:Array<{id:string;title:string;type:string;status:string;documents:number;createdAt:string}>;conversations:Array<{id:string;status:string;channel:string;customer:string;employee:string;createdAt:string;assignee:Assignee;messages:Array<{id:string;direction:string;content:string;createdAt:string}>;handoff:{reason:string;summary:string}|null}>;leads:Array<{id:string;stage:string;interest:string;customer:string;phone:string;email:string;createdAt:string;assignee:Assignee}>;appointments:Array<{id:string;service:string;status:string;startsAt:string;customer:string}>;customers:Array<{id:string;name:string}>;channels:Array<{id:string;type:string;status:string;employee:string;lastError:string}>;actions:Array<{key:string;name:string;description:string}>;members:Array<{id:string;role:string;user:{id:string;name:string|null;email:string}}> ;invitations:Array<{id:string;email:string;role:string;expiresAt:string}>;settings:{locale:string;timezone:string;dataRetentionDays:number;analyticsEnabled:boolean;aiTrainingOptIn:boolean;logoUrl:string;workingHours:{days:number[];start:string;end:string}};billing:{subscription:{plan:string;status:string;currentPeriodEnd:string};usage:{messages:number;conversations:number;actions:number}};activity:Array<{id:string;action:string;entityType:string;actor:string;createdAt:string}>;analyticsEvents:Array<{type:string;payload:Record<string,unknown>;createdAt:string}>;notifications:Array<{id:string;type:string;title:string;body:string;readAt:string|null;createdAt:string}>;automations:Array<{id:string;name:string;trigger:string;enabled:boolean;steps:Array<{actionKey:string;input:Record<string,unknown>}>}>};
type PlatformProps={workspaceName:string;userName:string;employee:{id:string;name:string;role:string;status:string};stats:{dialogs:number;leads:number;appointments:number;handoffs:number};data:PlatformData};
type MultiWorkspaceProps={workspaceId:string;workspaces:Array<{id:string;name:string;role:string}>};
export function Platform({ workspaceId, workspaces, workspaceName, userName, employee, stats, data }: PlatformProps&MultiWorkspaceProps) {
  const router=useRouter();
  const [locale,setLocale]=useState<"ru"|"en">(data.settings.locale==="en"?"en":"ru");const t=createTranslator(locale);
  const [page,setPage]=useState<PageId>("overview");
  const [running, setRunning] = useState(employee.status === "ACTIVE");
  const [drawer, setDrawer] = useState(false);
  const [collapsed,setCollapsed]=useState(false);
  const [searchOpen,setSearchOpen]=useState(false);
  const [searchQuery,setSearchQuery]=useState("");
  const [toast, setToast] = useState("");
  const select=(value:string)=>{const next=(value in pageLabels?value:pageByLabel.get(value)) as PageId|undefined;if(next)setPage(next);setDrawer(false)};
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(""), 2400); };
  const switchWorkspace=async(nextWorkspaceId:string)=>{if(nextWorkspaceId===workspaceId)return;const response=await sendJson("/api/workspaces/switch","POST",{workspaceId:nextWorkspaceId});if(response.ok){setPage("overview");router.refresh()}else notify(t("toast.workspaceSwitchFailed"))};
  const switchLocale=()=>{const next=locale==="ru"?"en":"ru";setLocale(next);document.documentElement.lang=next;window.localStorage.setItem("lemiri-locale",next);void sendJson("/api/settings","PATCH",{locale:next}).then(response=>{if(!response.ok)console.warn("Workspace locale was saved on this device only")}).catch(()=>undefined)};
  useEffect(()=>{const stored=window.localStorage.getItem("lemiri-locale");const preferred=stored==="en"||stored==="ru"?stored:locale;if(preferred!==locale)setLocale(preferred);document.documentElement.lang=preferred;fetch("/api/settings").then(response=>response.json()).then(body=>{const theme=body.settings?.theme??"system";document.documentElement.dataset.theme=theme==="system"?"":theme}).catch(()=>undefined)},[]);
  useEffect(()=>{const closeDesktopDrawer=()=>{if(window.innerWidth>760)setDrawer(false)};window.addEventListener("resize",closeDesktopDrawer);return()=>window.removeEventListener("resize",closeDesktopDrawer)},[]);
  useEffect(()=>{const handler=(event:KeyboardEvent)=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==="k"){event.preventDefault();setSearchOpen(value=>!value)}if(event.key==="Escape")setSearchOpen(false)};window.addEventListener("keydown",handler);return()=>window.removeEventListener("keydown",handler)},[]);
  const searchable:Array<{id:PageId;Icon:typeof Settings;label:string}>=[...sections.flatMap(group=>group.items.map(([id,Icon,key])=>({id:id as PageId,Icon,label:t(key as MessageKey)}))),{id:"settings",Icon:Settings,label:t("nav.settings")},{id:"notifications",Icon:Bell,label:t("nav.notifications")}];
  const searchResults=searchable.filter(item=>item.label.toLocaleLowerCase(locale).includes(searchQuery.trim().toLocaleLowerCase(locale)));

  return <div className={collapsed?"appShell sidebarCollapsed":"appShell"}>
    <aside className={drawer ? "sidebar open" : "sidebar"}>
      <div className="sideTop"><Logo compact={collapsed}/><button className="iconButton collapseButton" onClick={()=>setCollapsed(value=>!value)} aria-label={collapsed?"Развернуть боковую панель":"Свернуть боковую панель"}>{collapsed?<PanelLeftOpen size={18}/>:<PanelLeftClose size={18}/>}</button><button type="button" className="iconButton mobileOnly" onClick={() => setDrawer(false)} aria-label={locale==="ru"?"Закрыть меню":"Close menu"}><X size={18}/></button></div>
      <label className="workspace"><span className="workspaceAvatar">{workspaceName.slice(0,1).toUpperCase()}</span><span><b>{workspaceName}</b><small>{t("workspace.primary")}</small></span><select aria-label={locale==="en"?"Switch workspace":"Переключить пространство"} value={workspaceId} onChange={event=>switchWorkspace(event.target.value)}>{workspaces.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select><ChevronDown size={15}/></label>
      <nav>{sections.map(group=><div className="navGroup" key={group.title}><small>{t(group.title as MessageKey)}</small>{group.items.map(([id,Icon,key])=><button key={id} className={page===id?"navItem active":"navItem"} onClick={()=>select(id)}><Icon size={17}/><span>{t(key as MessageKey)}</span>{id==="conversations"&&<em>{data.conversations.filter(c=>c.status!=="CLOSED").length}</em>}</button>)}</div>)}</nav>
      <div className="sideBottom"><button className={page==="settings"?"navItem active":"navItem"} onClick={()=>select("settings")}><Settings size={17}/><span>{t("nav.settings")}</span></button><div className="profile"><span className="profileAvatar">{userName.slice(0,1).toUpperCase()}</span><span><b>{userName}</b></span></div><form action={logout}><button className="navItem logoutButton" type="submit"><LogOut size={17}/><span>{locale==="ru"?"Выйти":"Sign out"}</span></button></form></div>
    </aside>
    {drawer && <button className="scrim" onClick={() => setDrawer(false)} aria-label={t("common.closeMenu")}/>} 
    <main>
      <header className="topbar"><button type="button" className="iconButton mobileOnly" onClick={() => setDrawer(true)} aria-label={locale==="ru"?"Открыть меню":"Open menu"}><Menu size={20}/></button><button className="topSearch" onClick={()=>setSearchOpen(true)}><Search size={16}/><span>{t("common.search")}</span><kbd>Ctrl K</kbd></button><div className="topActions"><button type="button" className="languageButton" onClick={switchLocale} aria-label={locale==="ru"?"Switch to English":"Переключить на русский"}><Languages size={16}/><span>{locale==="ru"?"EN":"RU"}</span></button><button className="iconButton" onClick={()=>select("notifications")} aria-label={t("nav.notifications")}><Bell size={18}/>{data.notifications.some(n=>!n.readAt)&&<i/>}</button><button className="testButton" onClick={()=>select("testing")}><TestTube2 size={16}/> {t("common.test")}</button></div></header>
      {page==="overview"?<Dashboard locale={locale} running={running} setRunning={setRunning} select={select} notify={notify} employee={employee} stats={stats} data={data} userName={userName}/>:<FeaturePage locale={locale} page={pageLabels[page]} select={select} notify={notify} data={data} employeeId={employee.id} workspaceName={workspaceName} refresh={()=>router.refresh()}/>} 
    </main>
    {toast && <div className="toast"><Check size={17}/>{toast}</div>}
    {searchOpen&&<div className="commandOverlay" role="dialog" aria-modal="true" onMouseDown={()=>setSearchOpen(false)}><section className="commandPalette" onMouseDown={event=>event.stopPropagation()}><div className="commandInput"><Search size={19}/><input autoFocus value={searchQuery} onChange={event=>setSearchQuery(event.target.value)} placeholder={locale==="ru"?"Найти раздел…":"Find a section…"}/><button onClick={()=>setSearchOpen(false)}><X size={17}/></button></div><div className="commandResults">{searchResults.map(({id,Icon,label})=><button key={id} onClick={()=>{select(id);setSearchOpen(false);setSearchQuery("")}}><Icon size={18}/><span>{label}</span></button>)}{!searchResults.length&&<p>{locale==="ru"?"Ничего не найдено":"Nothing found"}</p>}</div></section></div>}
  </div>;
}

function Dashboard({ locale, running, setRunning, select, notify, employee, stats, data, userName }: { locale:string;running: boolean; setRunning: (v:boolean)=>void; select:(v:string)=>void; notify:(v:string)=>void;employee:PlatformProps["employee"];stats:PlatformProps["stats"];data:PlatformData;userName:string }) {
  const t=createTranslator(locale);const [periodDays,setPeriodDays]=useState(30);const cutoff=new Date(Date.now()-periodDays*86400_000);const inPeriod=(value:string)=>new Date(value)>=cutoff;const periodStats={dialogs:data.conversations.filter(row=>inPeriod(row.createdAt)).length,leads:data.leads.filter(row=>inPeriod(row.createdAt)).length,appointments:data.appointments.filter(row=>inPeriod(row.startsAt)).length,handoffs:data.conversations.filter(row=>row.handoff&&inPeriod(row.createdAt)).length};const metricDefinitions=[{label:t("metric.conversations"),value:periodStats.dialogs,type:"CONVERSATION_STARTED"},{label:t("metric.leads"),value:periodStats.leads,type:"LEAD_CREATED"},{label:t("metric.appointments"),value:periodStats.appointments,type:"APPOINTMENT_CREATED"},{label:t("metric.handoffs"),value:periodStats.handoffs,type:"HANDOFF_CREATED"}];const actualMetrics=metricDefinitions.map(metric=>({...metric,value:String(metric.value),delta:locale==="ru"?`За ${periodDays} дн.`:`${periodDays} days`,points:sevenDaySeries(data.analyticsEvents.filter(event=>inPeriod(event.createdAt)),metric.type)}));const readiness=Math.round(([employee.name,employee.role,data.sources.some(s=>s.status==="READY"),data.channels.some(c=>c.status==="CONNECTED")].filter(Boolean).length/4)*100);const recentConversations=data.conversations.slice(0,4);const recentActivity=data.activity.slice(0,4);const periods=locale==="ru"?[{d:7,l:"1 неделя"},{d:14,l:"2 недели"},{d:21,l:"3 недели"},{d:30,l:"1 месяц"},{d:60,l:"2 месяца"},{d:90,l:"3 месяца"},{d:182,l:"Полгода"},{d:365,l:"Год"}]:[{d:7,l:"1 week"},{d:14,l:"2 weeks"},{d:21,l:"3 weeks"},{d:30,l:"1 month"},{d:60,l:"2 months"},{d:90,l:"3 months"},{d:182,l:"6 months"},{d:365,l:"1 year"}];
  const toggleRunning=async()=>{const next=!running;const response=await fetch(`/api/employees/${employee.id}`,{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify({status:next?"ACTIVE":"PAUSED"})});if(response.ok){setRunning(next);notify(t(next?"toast.employeeStarted":"toast.employeePaused"))}else notify(t("toast.statusFailed"))};
  return <div className="page fadeIn">
    <section className="welcome"><div><p className="eyebrow">{t("common.workspace")}</p><h1>{t("dashboard.hello",{name:userName})}</h1><p>{t("dashboard.subtitle")}</p></div><PeriodDropdown locale={locale} value={periodDays} options={periods} onChange={setPeriodDays}/></section>
    <section className="metrics">{actualMetrics.map((m, i) => <article className="metric" key={m.label}><div><span>{m.label}</span><strong>{m.value}</strong><small className={i === 3 ? "neutral" : "positive"}>{m.delta}</small></div><Sparkline points={m.points}/></article>)}</section>
    <div className="contentGrid">
      <section className="employeeCard"><div className="sectionHead"><div><h2>{t("dashboard.employee")}</h2><p>{t(running?"dashboard.employeeWorking":"dashboard.employeePaused")}</p></div><button className="linkButton" onClick={() => select("Сотрудники")}>{t("dashboard.allEmployees")}</button></div><div className="employeeMain"><div className="employeeIdentity"><div className="botAvatar"><LemiriMark/><span className={running ? "online" : "offline"}/></div><div><div className="nameRow"><h3>{employee.name}</h3><span className={running ? "status success" : "status paused"}>{t(running?"dashboard.working":"dashboard.paused")}</span></div><p>{employee.role}</p></div></div><div className="employeeStats"><div><strong>{stats.dialogs}</strong><span>{t("dashboard.dialogCount")}</span></div><div><strong>{stats.leads}</strong><span>{t("dashboard.leadCount")}</span></div><div><strong>{stats.appointments}</strong><span>{t("dashboard.appointmentCount")}</span></div><div><strong>{stats.handoffs}</strong><span>{t("dashboard.handoffCount")}</span></div></div><div className="employeeButtons"><button className="primary" onClick={() => select("Сотрудники")}>{t("common.open")}</button><button onClick={() => notify(t("toast.testOpened"))}><TestTube2 size={16}/>{t("common.test")}</button><button className="iconButton" title={t(running?"common.pause":"common.start")} onClick={toggleRunning}>{running ? <Pause size={16}/> : <Play size={16}/>}</button></div></div></section>
      <section className="setupCard"><div className="setupTop"><span><LemiriMark/></span><div><h3>{t("setup.readiness",{percent:readiness})}</h3><p>{t(readiness===100?"setup.complete":"setup.incomplete")}</p></div></div><div className="progress"><i style={{width:`${readiness}%`}}/></div><div className="tasks"><button onClick={() => select("Знания")}><span><BookOpen size={17}/></span><div><b>{t(data.sources.some(s=>s.status==="READY")?"setup.knowledgeReady":"setup.knowledgeMissing")}</b><small>{t("setup.knowledgeHelp")}</small></div><em>{t(data.sources.some(s=>s.status==="READY")?"common.open":"common.add")}</em></button><button onClick={() => select("Каналы")}><span><Plug size={17}/></span><div><b>{t(data.channels.some(c=>c.status==="CONNECTED")?"setup.channelReady":"setup.channelMissing")}</b><small>{t("setup.channelHelp")}</small></div><em>{t(data.channels.some(c=>c.status==="CONNECTED")?"common.open":"common.add")}</em></button></div></section>
    </div>
    <div className="bottomGrid"><section><div className="sectionHead"><div><h2>{t("dashboard.events")}</h2><p>{t("dashboard.actualChanges")}</p></div><button className="linkButton" onClick={()=>select("Аналитика")}>{t("dashboard.allActivity")}</button></div>{recentActivity.length?<div className="activityList">{recentActivity.map(a=><div className="activityItem" key={a.id}><span className="activityIcon"><Activity/></span><div><b>{auditLabel(a.action,locale)}</b><p>{a.actor} · {entityLabel(a.entityType,locale)}</p></div><time>{new Date(a.createdAt).toLocaleString(dateLocale(locale),{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"})}</time></div>)}</div>:<Empty icon={Activity} title={t("dashboard.noEvents")} copy={t("dashboard.noEventsCopy")}/>}</section><section><div className="sectionHead"><div><h2>{t("dashboard.conversations")}</h2><p>{t("dashboard.recentRequests")}</p></div><button className="linkButton" onClick={() => select("Диалоги")}>{t("dashboard.openAll")}</button></div>{recentConversations.length?<div className="conversationList">{recentConversations.map(c=><button key={c.id} onClick={()=>select("Диалоги")}><span className="clientAvatar">{c.customer.slice(0,2).toUpperCase()}</span><span><b>{c.customer}</b><small>{c.messages.at(-1)?.content??t("dashboard.conversationCreated")}</small></span><span className="conversationMeta"><time>{c.messages.at(-1)?new Date(c.messages.at(-1)!.createdAt).toLocaleTimeString(dateLocale(locale),{hour:"2-digit",minute:"2-digit"}):""}</time></span></button>)}</div>:<Empty icon={MessageCircle} title={t("dashboard.noConversations")} copy={t("dashboard.noConversationsCopy")}/>}</section></div>
  </div>;
}

function FeaturePage({ locale, page, select, notify, data, employeeId, workspaceName, refresh }: {locale:string;page:string;select:(v:string)=>void;notify:(v:string)=>void;data:PlatformData;employeeId:string;workspaceName:string;refresh:()=>void}) {
  const catalog: Record<string,{title:string;copy:string;icon:typeof Settings;cta:string}> = {
    "Сотрудники": {title:"Ваши AI-сотрудники",copy:"Создавайте, обучайте и контролируйте цифровую команду.",icon:Bot,cta:"Новый сотрудник"},
    "Диалоги": {title:"Диалоги",copy:"Все обращения клиентов — в одном спокойном рабочем пространстве.",icon:MessageCircle,cta:"Открыть непрочитанные"},
    "Лиды": {title:"Лиды",copy:"Клиенты, чей интерес Lemiri уже квалифицировал.",icon:UserRoundPlus,cta:"Добавить лид"},
    "Записи": {title:"Записи",copy:"Встречи и услуги, которые Lemiri согласовал с клиентами.",icon:CalendarDays,cta:"Новая запись"},
    "Знания": {title:"Что должен знать Lemiri?",copy:"Добавьте сайт, документы и ответы вашей компании.",icon:BookOpen,cta:"Добавить источник"},
    "Действия": {title:"Действия",copy:"Разрешите сотрудникам безопасно выполнять операции в ваших системах.",icon:Zap,cta:"Настроить доступ"},
    "Каналы": {title:"Каналы связи",copy:"Подключите места, где клиенты уже пишут вам.",icon:Plug,cta:"Подключить канал"},
    "Интеграции": {title:"Интеграции",copy:"Передавайте лиды и записи в вашу CRM через подписанные webhooks.",icon:WandSparkles,cta:"Подключить CRM"},
    "Аналитика": {title:"Результаты работы",copy:"Понимайте, что Lemiri приносит бизнесу и где ему нужна помощь.",icon:BarChart3,cta:"Скачать отчёт"},
    "Тестирование": {title:"Тестовый режим",copy:"Поговорите с сотрудником до подключения реальных клиентов.",icon:TestTube2,cta:"Начать тест"},
    "Команда": {title:"Команда",copy:"Управляйте доступом людей к рабочему пространству.",icon:UserRoundPlus,cta:"Пригласить"},
    "Тариф и использование": {title:"Тариф и использование",copy:"Контролируйте лимиты и подписку Lemiri AI.",icon:CreditCard,cta:"Выбрать тариф"},
    "Настройки": {title:"Настройки",copy:"Компания, данные и конфиденциальность.",icon:Settings,cta:"Сохранить"},
    "Уведомления": {title:"Уведомления",copy:"События, которые требуют вашего внимания.",icon:Bell,cta:"Прочитать все"},
    "Правила": {title:"Правила и автоматизации",copy:"Определите, что Lemiri делает после важных событий.",icon:Zap,cta:"Новое правило"},
  };
  const englishText:Record<string,{title:string;copy:string}>={"Сотрудники":{title:"Your AI employees",copy:"Create, train and control your digital team."},"Диалоги":{title:"Conversations",copy:"Every customer request in one focused workspace."},"Лиды":{title:"Leads",copy:"Customers whose interest Lemiri has qualified."},"Записи":{title:"Appointments",copy:"Meetings and services agreed with customers."},"Знания":{title:"What should Lemiri know?",copy:"Add your website, documents and company answers."},"Действия":{title:"Actions",copy:"Allow employees to perform safe operations in your systems."},"Правила":{title:"Rules and automations",copy:"Define what Lemiri does after important events."},"Каналы":{title:"Communication channels",copy:"Connect the places where customers already contact you."},"Интеграции":{title:"Integrations",copy:"Send leads and appointments to your CRM using signed webhooks."},"Аналитика":{title:"Performance",copy:"See what Lemiri delivers and where it needs help."},"Тестирование":{title:"Test mode",copy:"Talk to the employee before connecting real customers."},"Команда":{title:"Team",copy:"Manage access to your workspace."},"Тариф и использование":{title:"Plan and usage",copy:"Control Lemiri AI limits and subscription."},"Настройки":{title:"Settings",copy:"Company, data and privacy."},"Уведомления":{title:"Notifications",copy:"Events that require your attention."}};
  const baseItem = catalog[page] ?? {title:page,copy:"Настройки рабочего пространства.",icon:Settings,cta:"Настроить"};const item=locale==="en"&&englishText[page]?{...baseItem,...englishText[page]}:baseItem; const Icon=item.icon;const t=createTranslator(locale);
  let content:React.ReactNode=null;
  switch(page){
    case"Сотрудники":content=<EmployeesView locale={locale} rows={data.employees} members={data.members} notify={notify} refresh={refresh}/>;break;
    case"Знания":content=<KnowledgeManager locale={locale} rows={data.sources} notify={notify} refresh={refresh}/>;break;
    case"Диалоги":content=<ConversationsView locale={locale} rows={data.conversations} members={data.members} notify={notify} refresh={refresh}/>;break;
    case"Лиды":content=<LeadsView locale={locale} rows={data.leads} members={data.members} notify={notify} refresh={refresh}/>;break;
    case"Записи":content=<AppointmentsView locale={locale} rows={data.appointments} customers={data.customers} notify={notify} refresh={refresh}/>;break;
    case"Каналы":content=<ChannelsView locale={locale} rows={data.channels} employees={data.employees} notify={notify} refresh={refresh}/>;break;
    case"Интеграции":content=<IntegrationsView locale={locale} notify={notify}/>;break;
    case"Действия":content=<ActionsView locale={locale} actions={data.actions} employees={data.employees} notify={notify} refresh={refresh}/>;break;
    case"Правила":content=<AutomationsView locale={locale} rows={data.automations} actions={data.actions} notify={notify} refresh={refresh}/>;break;
    case"Аналитика":content=<div className="stackedPage"><AnalyticsView locale={locale} stats={data.analyticsEvents} totals={{dialogs:data.conversations.length,leads:data.leads.length,appointments:data.appointments.length,handoffs:data.conversations.filter(c=>c.handoff).length}} activity={data.activity}/><InsightsPanel locale={locale}/></div>;break;
    case"Команда":content=<TeamView locale={locale} members={data.members} invitations={data.invitations} notify={notify} refresh={refresh}/>;break;
    case"Тариф и использование":content=<BillingView locale={locale} value={data.billing} notify={notify}/>;break;
    case"Настройки":content=<SettingsView locale={locale} value={data.settings} workspaceName={workspaceName} notify={notify} refresh={refresh}/>;break;
    case"Уведомления":content=<NotificationsView locale={locale} rows={data.notifications} notify={notify} refresh={refresh}/>;break;
    case"Тестирование":content=<TestLab locale={locale} employeeId={employeeId} notify={notify}/>;
  }
  return <div className="page fadeIn"><section className="welcome"><div><p className="eyebrow">{t("common.workspace")}</p><h1>{item.title}</h1><p>{item.copy}</p></div></section>{content??<section className="featureCanvas"><div className="featureIcon"><Icon size={24}/></div><h2>Раздел «{page}»</h2><p>Следующий функциональный модуль в активной реализации.</p><div className="featureActions"><button onClick={() => select("Обзор")}>Вернуться к обзору</button></div></section>}</div>;
}

async function sendJson(url:string,method:string,payload:unknown){return fetch(url,{method,headers:{"content-type":"application/json"},body:JSON.stringify(payload)})}

function AssignmentSelect({locale,entityType,entityId,value,members,notify,refresh}:{locale:string;entityType:"EMPLOYEE"|"CONVERSATION"|"LEAD";entityId:string;value:string;members:PlatformData["members"];notify:(v:string)=>void;refresh:()=>void}){
  const t=createTranslator(locale);const assignable=members.filter(member=>member.role!=="VIEWER");
  const assign=async(memberId:string)=>{const response=await sendJson("/api/assignments","PUT",{entityType,entityId,memberId:memberId||null});if(response.ok){notify(t("assignment.saved"));refresh()}else notify(t("assignment.failed"))};
  return <label className="assignmentSelect"><span>{t("assignment.manager")}</span><select aria-label={t("assignment.manager")} value={value} onChange={event=>assign(event.target.value)}><option value="">{t("assignment.unassigned")}</option>{assignable.map(member=><option key={member.id} value={member.id}>{member.user.name??member.user.email}</option>)}</select></label>;
}

function EmployeesView({locale,rows,members,notify,refresh}:{locale:string;rows:PlatformData["employees"];members:PlatformData["members"];notify:(v:string)=>void;refresh:()=>void}){
  const t=createTranslator(locale);const localizedRole=(value:string)=>employeeRoleLabel(value,locale==="en"?"en":"ru");const localizedTone=(value:string)=>employeeToneLabel(value,locale==="en"?"en":"ru");
  const [open,setOpen]=useState(false);const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget));const response=await sendJson("/api/employees","POST",values);if(response.ok){setOpen(false);notify(t("employees.created"));refresh()}else notify(t("employees.invalid"))};
  return <section className="dataSection"><div className="dataToolbar"><b>{t("employees.count",{count:rows.length})}</b><button className="primary miniPrimary" onClick={()=>setOpen(!open)}><Plus size={15}/>{t("employees.new")}</button></div>{open&&<form className="inlineForm" onSubmit={submit}><label>{t("employees.name")}<input name="name" required/></label><label>{t("employees.role")}<select name="role"><option value="Администратор">{t("role.admin")}</option><option value="Менеджер продаж">{t("role.sales")}</option><option value="Поддержка">{t("role.support")}</option></select></label><label className="wide">{t("employees.goal")}<input name="goal" required minLength={10}/></label><label>{t("employees.tone")}<select name="tone"><option value="Тёплый и профессиональный">{t("tone.warm")}</option><option value="Краткий и деловой">{t("tone.concise")}</option></select></label><button className="primary">{t("employees.create")}</button></form>}<div className="cardsGrid">{rows.map(row=><article className="resourceCard" key={row.id}><div className="resourceIcon"><Bot size={18}/></div><div className="resourceTitle"><h3>{row.name}</h3><span className={`status ${row.status==="ACTIVE"?"success":"paused"}`}>{t(row.status==="ACTIVE"?"dashboard.working":row.status==="PAUSED"?"dashboard.paused":"employees.configuring")}</span></div><p>{localizedRole(row.role)}</p><AssignmentSelect locale={locale} entityType="EMPLOYEE" entityId={row.id} value={row.assignee?.id??""} members={members} notify={notify} refresh={refresh}/><dl><div><dt>{t("employees.task")}</dt><dd>{row.goal}</dd></div><div><dt>{t("employees.communication")}</dt><dd>{localizedTone(row.tone)}</dd></div></dl></article>)}</div></section>
}

type HealthData={score:number;sources:{total:number;ready:number;failed:number};chunks:number;gaps:Array<{id:string;question:string;occurrences:number}>};
function KnowledgeHealth({locale}:{locale:string}){const t=createTranslator(locale);const [value,setValue]=useState<HealthData>();useEffect(()=>{fetch("/api/knowledge/health").then(r=>r.json()).then(setValue)},[]);if(!value)return null;return <section className="healthPanel"><div className="healthScore"><strong>{value.score}</strong><span>{t("knowledge.health")}</span></div><div><b>{t("knowledge.readySources",{ready:value.sources.ready,total:value.sources.total})}</b><p>{t("knowledge.chunks",{chunks:value.chunks,failed:value.sources.failed})}</p></div><div className="healthGaps"><b>{t("knowledge.gaps")}</b>{value.gaps.length?value.gaps.slice(0,3).map(g=><p key={g.id}>{g.question}<span>{g.occurrences}×</span></p>):<p>{t("knowledge.noGaps")}</p>}</div></section>}

function KnowledgeView({rows,notify,refresh}:{rows:PlatformData["sources"];notify:(v:string)=>void;refresh:()=>void}){
  const [open,setOpen]=useState(false);const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget));const response=await sendJson("/api/knowledge","POST",values);if(response.ok){setOpen(false);notify("Знания добавлены и разбиты на фрагменты");refresh()}else notify("Не удалось добавить источник")};
 return <section className="dataSection"><div className="dataToolbar"><div><b>{rows.length} источников</b><small>Ответы Lemiri строятся только на готовых источниках</small></div><button className="primary miniPrimary" onClick={()=>setOpen(!open)}><Plus size={15}/>Добавить источник</button></div>{open&&<form className="inlineForm stacked" onSubmit={submit}><div className="formRow"><label>Название<input name="title" required placeholder="Услуги и цены"/></label><label>Тип<select name="type"><option value="TEXT">Текст</option><option value="FAQ">FAQ</option><option value="WEBSITE">Сайт</option></select></label></div><label>Информация<textarea name="content" required minLength={10} placeholder="Вставьте проверенную информацию компании…"/></label><button className="primary">Сохранить и обработать</button></form>} {rows.length?<div className="tableWrap"><table><thead><tr><th>Источник</th><th>Тип</th><th>Документы</th><th>Состояние</th></tr></thead><tbody>{rows.map(row=><tr key={row.id}><td><span className="tableTitle"><FileText size={16}/>{row.title}</span></td><td>{row.type}</td><td>{row.documents}</td><td><span className={`status ${row.status==="READY"?"success":"paused"}`}>{row.status==="READY"?"Готов":row.status==="FAILED"?"Ошибка":"Обрабатывается"}</span></td></tr>)}</tbody></table></div>:<Empty icon={BookOpen} title="Пока нет знаний" copy="Добавьте информацию компании, прежде чем запускать сотрудника."/>}</section>
}

function ConversationsView({locale,rows,members,notify,refresh}:{locale:string;rows:PlatformData["conversations"];members:PlatformData["members"];notify:(v:string)=>void;refresh:()=>void}){
  const t=createTranslator(locale);const [selected,setSelected]=useState(rows[0]?.id??"");const [sending,setSending]=useState(false);const current=rows.find(row=>row.id===selected);
  const refreshRef=useRef(refresh);useEffect(()=>{refreshRef.current=refresh},[refresh]);
  useEffect(()=>{if(!selected)return;const events=new EventSource(`/api/conversations/${selected}/events`);const onMessage=()=>refreshRef.current();events.addEventListener("message",onMessage);return()=>{events.removeEventListener("message",onMessage);events.close()}},[selected]);
  const takeover=async()=>{if(!current)return;const response=await fetch(`/api/conversations/${current.id}/takeover`,{method:"POST"});if(response.ok){notify(t("conversations.taken"));refresh()}else notify(t("conversations.takeFailed"))};
  const reply=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();if(!current||sending)return;const form=event.currentTarget;const content=String(new FormData(form).get("content")??"").trim();if(!content)return;setSending(true);const response=await sendJson(`/api/conversations/${current.id}/messages`,"POST",{content});setSending(false);if(response.ok){form.reset();refresh()}else notify(t("conversations.replyFailed"))};
  return rows.length?<section className="conversationWorkspace"><aside>{rows.map(row=><button className={selected===row.id?"selected":""} key={row.id} onClick={()=>setSelected(row.id)}><span className="clientAvatar">{row.customer.slice(0,2).toUpperCase()}</span><span><b>{row.customer}</b><small>{row.messages.at(-1)?.content??t("conversations.new")}</small></span><em>{row.channel}</em></button>)}</aside>{current&&<div className="chatPane"><header><div><b>{current.customer}</b><small>{current.channel} · {current.employee}</small></div><AssignmentSelect locale={locale} entityType="CONVERSATION" entityId={current.id} value={current.assignee?.id??""} members={members} notify={notify} refresh={refresh}/><button onClick={takeover} disabled={current.status==="HUMAN_ACTIVE"}>{t(current.status==="HUMAN_ACTIVE"?"conversations.youReply":"conversations.take")}</button></header><div className="messageStream">{current.messages.map(message=><div key={message.id} className={message.direction==="INBOUND"?"bubble inbound":"bubble outbound"}><p>{message.content}</p><time>{new Date(message.createdAt).toLocaleTimeString(dateLocale(locale),{hour:"2-digit",minute:"2-digit"})}</time></div>)}</div>{current.handoff&&<div className="handoffBanner"><Bell size={17}/><div><b>{t("conversations.humanNeeded")}</b><p>{current.handoff.summary}</p></div></div>}{current.status==="HUMAN_ACTIVE"&&<form className="humanReply" onSubmit={reply}><input name="content" maxLength={4000} required autoComplete="off" placeholder={t("conversations.replyPlaceholder")}/><button disabled={sending}>{sending?"…":t("conversations.send")}</button></form>}</div>}</section>:<Empty icon={MessageCircle} title={t("conversations.empty")} copy={t("conversations.emptyCopy")}/>;
}

function LeadsView({locale,rows,members,notify,refresh}:{locale:string;rows:PlatformData["leads"];members:PlatformData["members"];notify:(v:string)=>void;refresh:()=>void}){
 const t=createTranslator(locale);return <section className="dataSection"><div className="dataToolbar"><div><b>{t("leads.count",{count:rows.length})}</b><small>{locale==="ru"?"Лиды создаёт ИИ после квалификации клиента":"Leads are created by AI after customer qualification"}</small></div></div>{rows.length?<div className="tableWrap"><table><thead><tr><th>{t("leads.customer")}</th><th>{t("leads.interest")}</th><th>{t("leads.contact")}</th><th>{t("assignment.manager")}</th><th>{t("leads.stage")}</th></tr></thead><tbody>{rows.map(row=><tr key={row.id}><td><b>{row.customer}</b></td><td>{row.interest||"—"}</td><td>{row.phone||row.email||"—"}</td><td><AssignmentSelect locale={locale} entityType="LEAD" entityId={row.id} value={row.assignee?.id??""} members={members} notify={notify} refresh={refresh}/></td><td><span className="status paused">{row.stage}</span></td></tr>)}</tbody></table></div>:<Empty icon={UserRoundPlus} title={t("leads.empty")} copy={t("leads.emptyCopy")}/>}</section>
}
function AppointmentsView({locale,rows,customers,notify,refresh}:{locale:string;rows:PlatformData["appointments"];customers:PlatformData["customers"];notify:(v:string)=>void;refresh:()=>void}){
 void customers;void notify;void refresh;const t=createTranslator(locale);const status=(value:string)=>value==="SCHEDULED"?t("status.scheduled"):value==="CONFIRMED"?t("status.confirmed"):value==="CANCELLED"?t("status.cancelled"):value==="COMPLETED"?t("status.completed"):value;return <section className="dataSection"><div className="dataToolbar"><div><b>{t("appointments.count",{count:rows.length})}</b><small>{locale==="ru"?"Записи создаёт ИИ после подтверждения времени клиентом":"Appointments are created by AI after the customer confirms the time"}</small></div></div>{rows.length?<div className="cardsGrid appointments">{rows.map(row=><article className="appointmentCard" key={row.id}><div className="dateBox"><b>{new Date(row.startsAt).getDate()}</b><small>{new Date(row.startsAt).toLocaleString(dateLocale(locale),{month:"short"})}</small></div><div><h3>{row.service}</h3><p>{row.customer}</p><small>{new Date(row.startsAt).toLocaleString(dateLocale(locale),{hour:"2-digit",minute:"2-digit",weekday:"long"})}</small></div><span className="status success">{status(row.status)}</span></article>)}</div>:<Empty icon={CalendarDays} title={t("appointments.empty")} copy={t("appointments.emptyCopy")}/>}</section>
}
function ChannelsView({locale,rows,employees,notify,refresh}:{locale:string;rows:PlatformData["channels"];employees:PlatformData["employees"];notify:(v:string)=>void;refresh:()=>void}){
 const t=createTranslator(locale);const types=["WEBSITE","TELEGRAM","WHATSAPP","EMAIL"] as const;const [kind,setKind]=useState<(typeof types)[number]|null>(null);const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.currentTarget));const type=String(v.type);const config=type==="WEBSITE"?{allowedOrigins:String(v.allowedOrigins??"").split(",").map(x=>x.trim()).filter(Boolean)}:type==="TELEGRAM"?{botToken:String(v.botToken),webhookSecret:String(v.webhookSecret)}:type==="WHATSAPP"?{accessToken:String(v.accessToken),phoneNumberId:String(v.phoneNumberId),verifyToken:String(v.verifyToken),appSecret:String(v.appSecret)}:{inboundAddress:String(v.inboundAddress),webhookSecret:String(v.webhookSecret)};const response=await sendJson("/api/channels","POST",{type,employeeId:v.employeeId,config});const body=await response.json();if(response.ok){setKind(null);notify(t("channels.connectedToast"));refresh()}else notify(body.error==="INVALID_CREDENTIALS"?t("channels.invalidCredentials"):body.error??t("channels.connectFailed"))};const disconnect=async(id:string)=>{const response=await fetch(`/api/channels/${id}`,{method:"DELETE"});if(response.ok){notify(t("channels.disconnectedToast"));refresh()}else notify(t("channels.disconnectFailed"))};
 return <section className="dataSection"><div className="dataToolbar"><div><b>{t("channels.title")}</b><small>{t("channels.security")}</small></div><div className="toolbarButtons">{types.map(type=><button key={type} disabled={!employees.length} onClick={()=>setKind(type)}><Plus size={14}/>{type==="WEBSITE"?t("channels.website"):type}</button>)}</div></div>{!employees.length&&<p className="connectorError">{t("channels.emptyEmployees")}</p>}{kind&&employees.length>0&&<form className="inlineForm stacked" onSubmit={submit}><input type="hidden" name="type" value={kind}/><label>{t("channels.employee")}<select name="employeeId" required>{employees.map(e=><option key={e.id} value={e.id}>{e.name}</option>)}</select></label>{kind==="WEBSITE"&&<label>{t("channels.allowedSites")}<input name="allowedOrigins" placeholder="https://example.com"/></label>}{kind==="TELEGRAM"&&<><label>Bot token<input name="botToken" type="password" autoComplete="off" required/></label><label>Webhook secret<input name="webhookSecret" type="password" autoComplete="off" minLength={16} required/></label></>}{kind==="WHATSAPP"&&<><div className="formRow"><label>Access token<input name="accessToken" type="password" autoComplete="off" required/></label><label>Phone number ID<input name="phoneNumberId" required/></label></div><div className="formRow"><label>Webhook verify token<input name="verifyToken" type="password" autoComplete="off" minLength={16} required/></label><label>Meta app secret<input name="appSecret" type="password" autoComplete="off" minLength={16} required/></label></div></>}{kind==="EMAIL"&&<><label>{t("channels.inboundAddress")}<input name="inboundAddress" type="email" required/></label><label>Webhook secret<input name="webhookSecret" type="password" autoComplete="off" minLength={16} required/></label></>}<button className="primary">{t("channels.connect")}</button></form>}<div className="connectorGrid">{types.map(type=>{const row=rows.find(r=>r.type===type);const webhookPath=`/api/webhooks/${type.toLowerCase()}/${row?.id??""}`;return <article className="connectorCard" key={type}><div className="connectorLogo"><Plug size={20}/></div><div><h3>{type==="WEBSITE"?t("channels.websiteChat"):type}</h3><p>{row?t("channels.assignedEmployee",{name:row.employee}):t("channels.notConnected")}</p>{row?.status==="CONNECTED"&&type!=="WEBSITE"&&<small className="connectorHint">{t("channels.webhook",{path:webhookPath})}</small>}{row?.lastError&&<small className="connectorError">{row.lastError}</small>}</div><span className={`status ${row?.status==="CONNECTED"?"success":"paused"}`}>{row?.status==="CONNECTED"?t("channels.connected"):row?.status==="ERROR"?t("channels.error"):t("channels.notConnected")}</span>{row?.status==="CONNECTED"&&<button className="disconnect" onClick={()=>disconnect(row.id)}>{t("channels.disconnect")}</button>}</article>})}</div></section>
}

function ActionsView({locale,actions,employees,notify,refresh}:{locale:string;actions:PlatformData["actions"];employees:PlatformData["employees"];notify:(v:string)=>void;refresh:()=>void}){
 const t=createTranslator(locale);const label=(key:string,fallback:string)=>key==="createLead"?t("action.createLead.name"):key==="createAppointment"?t("action.createAppointment.name"):key==="notifyManager"?t("action.notifyManager.name"):key==="handoffToHuman"?t("action.handoffToHuman.name"):fallback;const description=(key:string,fallback:string)=>key==="createLead"?t("action.createLead.copy"):key==="createAppointment"?t("action.createAppointment.copy"):key==="notifyManager"?t("action.notifyManager.copy"):key==="handoffToHuman"?t("action.handoffToHuman.copy"):fallback;const [employeeId,setEmployeeId]=useState(employees[0]?.id??"");const employee=employees.find(e=>e.id===employeeId);const toggle=async(key:string,enabled:boolean)=>{if(!employeeId)return;const response=await sendJson("/api/actions/permissions","PUT",{employeeId,actionKey:key,enabled});if(response.ok){notify(enabled?t("actions.enabled"):t("actions.disabled"));refresh()}else notify(t("actions.updateFailed"))};return <section className="dataSection"><div className="dataToolbar"><div><b>{t("actions.allowed")}</b><small>{t("actions.defaultOff")}</small></div>{employees.length>0&&<select className="employeeSelect" value={employeeId} onChange={e=>setEmployeeId(e.target.value)}>{employees.map(e=><option key={e.id} value={e.id}>{e.name}</option>)}</select>}</div>{!employees.length?<Empty icon={Zap} title={t("actions.noEmployees")} copy={t("actions.defaultOff")}/>:actions.length?<div className="permissionList">{actions.map(action=>{const enabled=employee?.permissions.some(p=>p.key===action.key&&p.enabled)??false;return <div key={action.key}><span className="permissionIcon"><Zap size={17}/></span><div><b>{label(action.key,action.name)}</b><p>{description(action.key,action.description)}</p></div><button role="switch" aria-checked={enabled} className={enabled?"switch on":"switch"} onClick={()=>toggle(action.key,!enabled)}><i/></button></div>})}</div>:<Empty icon={Zap} title={t("actions.empty")} copy={t("actions.emptyCopy")}/>}<div className="securityNote"><CircleHelp size={17}/><p><b>{t("actions.ownerControl")}</b><br/>{t("actions.auditCopy")}</p></div></section>
}

type Insight={type:string;severity:string;title:string;description:string};
function InsightsPanel({locale}:{locale:string}){const t=createTranslator(locale);const [items,setItems]=useState<Insight[]>([]);const [failed,setFailed]=useState(false);useEffect(()=>{fetch("/api/insights").then(r=>{if(!r.ok)throw new Error("INSIGHTS_LOAD_FAILED");return r.json()}).then(value=>setItems([...(value.saved??[]),...(value.live??[])])).catch(()=>setFailed(true))},[]);const severity=(value:string)=>value==="HIGH"?t("severity.high"):value==="MEDIUM"?t("severity.medium"):value==="LOW"?t("severity.low"):value;return <section className="insightsPanel"><div className="sectionHead"><div><h2>{t("insights.title")}</h2><p>{t("insights.subtitle")}</p></div></div>{failed?<Empty icon={Sparkles} title={t("insights.loadFailed")} copy={t("insights.emptyCopy")}/>:items.length?<div className="insightGrid">{items.map((item,index)=><article key={`${item.type}-${index}`}><span className={`status ${item.severity==="HIGH"?"paused":"success"}`}>{severity(item.severity)}</span><b>{item.title}</b><p>{item.description}</p></article>)}</div>:<Empty icon={Sparkles} title={t("insights.empty")} copy={t("insights.emptyCopy")}/>}</section>}

function AnalyticsView({locale,stats,totals,activity}:{locale:string;stats:PlatformData["analyticsEvents"];totals:{dialogs:number;leads:number;appointments:number;handoffs:number};activity:PlatformData["activity"]}){
 const t=createTranslator(locale);const responses=stats.filter(e=>e.type==="AI_RESPONSE");const confidence=responses.length?Math.round(responses.reduce((sum,e)=>sum+Number(e.payload.confidence??0),0)/responses.length*100):0;const values=[totals.dialogs,totals.leads,totals.appointments,totals.handoffs];const labels=[t("analytics.conversations"),t("analytics.leads"),t("analytics.appointments"),t("analytics.transfers")];const max=Math.max(...values,1);return <div className="analyticsLayout"><section className="analyticsCards"><article><span>{t("analytics.conversations")}</span><strong>{totals.dialogs}</strong></article><article><span>{t("analytics.leadConversion")}</span><strong>{totals.dialogs?Math.round(totals.leads/totals.dialogs*100):0}%</strong></article><article><span>{t("analytics.confidence")}</span><strong>{confidence}%</strong></article><article><span>{t("analytics.handoffs")}</span><strong>{totals.handoffs}</strong></article></section><section className="chartCard"><div className="sectionHead"><div><h2>{t("analytics.results")}</h2><p>{t("analytics.actualData")}</p></div></div><div className="barChart">{labels.map((label,i)=><div key={label}><span style={{height:`${Math.max(5,values[i]!/max*100)}%`}}/><small>{label}</small><b>{values[i]}</b></div>)}</div></section><section className="activityCard"><div className="sectionHead"><div><h2>{t("analytics.audit")}</h2><p>{t("analytics.auditSubtitle")}</p></div></div>{activity.length?<div className="auditList">{activity.map(item=><div key={item.id}><span><Activity size={14}/></span><div><b>{auditLabel(item.action,locale)}</b><small>{item.actor||t("analytics.systemActor")} · {entityLabel(item.entityType,locale)}</small></div><time>{new Date(item.createdAt).toLocaleString(dateLocale(locale))}</time></div>)}</div>:<Empty icon={Activity} title={t("analytics.auditEmpty")} copy={t("analytics.auditEmptyCopy")}/>}</section></div>
}

function TeamView({locale,members,invitations,notify,refresh}:{locale:string;members:PlatformData["members"];invitations:PlatformData["invitations"];notify:(v:string)=>void;refresh:()=>void}){
 const t=createTranslator(locale);const roleLabel=(role:string)=>role==="OWNER"?t("team.owner"):role==="ADMIN"?t("team.admin"):role==="MANAGER"?t("team.manager"):role==="VIEWER"?t("team.viewer"):role;const [open,setOpen]=useState(false);const [devLink,setDevLink]=useState("");const invite=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const response=await sendJson("/api/team","POST",Object.fromEntries(new FormData(e.currentTarget)));const body=await response.json();if(response.ok){setOpen(false);setDevLink(body.developmentInviteUrl??"");notify(body.delivery==="SENT"?t("team.inviteSent"):t("team.inviteCreated"));refresh()}else notify(t("team.inviteFailed"))};const updateRole=async(id:string,role:string)=>{const response=await sendJson(`/api/team/members/${id}`,"PATCH",{role});if(response.ok){notify(t("team.roleChanged"));refresh()}else notify(t("team.roleFailed"))};const remove=async(id:string)=>{if(!confirm(t("team.confirmRemove")))return;const response=await fetch(`/api/team/members/${id}`,{method:"DELETE"});if(response.ok){notify(t("team.removed"));refresh()}else notify(t("team.removeFailed"))};return <section className="dataSection"><div className="dataToolbar"><b>{t("team.count",{count:members.length})}</b><button className="primary miniPrimary" onClick={()=>setOpen(!open)}><Plus size={15}/>{t("team.invite")}</button></div>{open&&<form className="inlineForm" onSubmit={invite}><label>Email<input type="email" name="email" required/></label><label>{t("team.role")}<select name="role"><option value="MANAGER">{t("team.manager")}</option><option value="ADMIN">{t("team.admin")}</option><option value="VIEWER">{t("team.viewer")}</option></select></label><button className="primary">{t("team.send")}</button></form>}{devLink&&<div className="devLink"><b>{t("team.developmentLink")}</b><code>{devLink}</code></div>}<div className="memberList">{members.map(member=><div key={member.id}><span className="profileAvatar">{(member.user.name??member.user.email).slice(0,1).toUpperCase()}</span><div><b>{member.user.name??t("team.noName")}</b><small>{member.user.email}</small></div>{member.role==="OWNER"?<span className="status success">{t("team.owner")}</span>:<><select aria-label={t("team.role")} value={member.role} onChange={e=>updateRole(member.id,e.target.value)}><option value="ADMIN">{t("team.admin")}</option><option value="MANAGER">{t("team.manager")}</option><option value="VIEWER">{t("team.viewer")}</option></select><button onClick={()=>remove(member.id)}>{t("team.remove")}</button></>}</div>)}</div>{invitations.length>0&&<div className="pendingInvites"><h3>{t("team.pending")}</h3>{invitations.map(i=><p key={i.id}>{i.email}<span>{roleLabel(i.role)} · {t("team.expires",{date:new Date(i.expiresAt).toLocaleDateString(dateLocale(locale))})}</span></p>)}</div>}</section>
}

type BillingValue=PlatformData["billing"]&{usage:PlatformData["billing"]["usage"]&{aiUsage:number;knowledgeBytes:number;activeEmployees:number};plans:Record<string,{key:string;name:string;conversationLimit:number;employeeLimit:number}>};
function BillingView({locale,value,notify}:{locale:string;value:PlatformData["billing"];notify:(v:string)=>void}){
 const t=createTranslator(locale);const details=value as BillingValue;const numberLocale=dateLocale(locale);const current=details.plans[details.subscription.plan]??details.plans.TRIAL;const checkout=async(plan:"START"|"GROWTH")=>{const response=await sendJson("/api/billing","POST",{plan});const body=await response.json();if(response.ok&&body.url)window.location.assign(body.url);else notify(body.error==="BILLING_PROVIDER_NOT_CONFIGURED"?t("billing.providerMissing"):t("billing.checkoutFailed"))};const storage=details.usage.knowledgeBytes<1_000_000?`${Math.ceil(details.usage.knowledgeBytes/1024).toLocaleString(numberLocale)} KB`:`${(details.usage.knowledgeBytes/1_000_000).toLocaleString(numberLocale,{maximumFractionDigits:1})} MB`;
 const plans=locale==="ru"?[{key:"FREE",name:"Free",price:"$0 / 14 дней",copy:"Один раз, затем только по подписке. Тест ИИ-сотрудника, чат на сайте, ограниченный объём сообщений."},{key:"START",name:"Starter",price:"$19 / мес",copy:"Для первого запуска. 1 ИИ-сотрудник, сайт + Telegram, база знаний, лиды и базовая аналитика."},{key:"GROWTH",name:"Pro",price:"$49 / мес",copy:"Для активных продаж и записи. WhatsApp, Telegram, сайт, CRM, календарь, автоматические действия, больше лимитов."},{key:"BUSINESS",name:"Business",price:"$99 / мес",copy:"Для команды и нескольких процессов. Несколько ИИ-сотрудников, повышенные лимиты, расширенная аналитика, интеграции и приоритетная поддержка."},{key:"ENTERPRISE",name:"Enterprise",price:"Индивидуально",copy:"Для больших объёмов. Кастомные интеграции, SLA и отдельные условия."}]:[{key:"FREE",name:"Free",price:"$0 / 14 days",copy:"One time, then subscription only. AI employee test, website chat and limited messages."},{key:"START",name:"Starter",price:"$19 / month",copy:"For your first launch. 1 AI employee, website + Telegram, knowledge base, leads and basic analytics."},{key:"GROWTH",name:"Pro",price:"$49 / month",copy:"For active sales and booking. WhatsApp, Telegram, website, CRM, calendar, automations and higher limits."},{key:"BUSINESS",name:"Business",price:"$99 / month",copy:"For teams and multiple processes. Several AI employees, higher limits, advanced analytics, integrations and priority support."},{key:"ENTERPRISE",name:"Enterprise",price:"Custom",copy:"For high volumes. Custom integrations, SLA and individual terms."}];
 return <div className="billingLayout"><section className="currentPlan"><div><span className="eyebrow">{t("billing.currentPlan")}</span><h2>{current?.name??"Free"}</h2><p>{details.subscription.status}</p></div><div className="usageCircle"><strong>{details.usage.conversations.toLocaleString(numberLocale)}</strong><small>{locale==="ru"?"диалогов":"conversations"}</small></div></section><section className="usageGrid"><article><span>{t("billing.aiUsage")}</span><strong>{details.usage.aiUsage.toLocaleString(numberLocale)}</strong></article><article><span>{t("billing.knowledge")}</span><strong>{storage}</strong></article><article><span>{t("billing.activeEmployees")}</span><strong>{details.usage.activeEmployees.toLocaleString(numberLocale)}</strong></article><article><span>{t("billing.aiActions")}</span><strong>{details.usage.actions.toLocaleString(numberLocale)}</strong></article></section><section className="plansGrid pricingFive">{plans.map(plan=><article key={plan.key} className={plan.key==="GROWTH"?"recommended":""}>{plan.key==="GROWTH"&&<span>{t("billing.recommended")}</span>}<h3>{plan.name}</h3><strong>{plan.price}</strong><p>{plan.copy}</p>{plan.key==="START"||plan.key==="GROWTH"?<button className={plan.key==="GROWTH"?"primary":""} onClick={()=>checkout(plan.key as "START"|"GROWTH")}>{locale==="ru"?"Выбрать тариф":"Choose plan"}</button>:plan.key==="ENTERPRISE"?<a className="planButton" href="mailto:sales@lemiri.ai">{locale==="ru"?"Связаться с нами":"Contact us"}</a>:<button disabled>{plan.key==="FREE"?(locale==="ru"?"Пробный период":"Trial"):(locale==="ru"?"Скоро":"Coming soon")}</button>}</article>)}</section></div>
}
function SettingsView({locale,value,workspaceName,notify,refresh}:{locale:string;value:PlatformData["settings"];workspaceName:string;notify:(v:string)=>void;refresh:()=>void}){
 const t=createTranslator(locale);const weekdays=[t("weekday.sun"),t("weekday.mon"),t("weekday.tue"),t("weekday.wed"),t("weekday.thu"),t("weekday.fri"),t("weekday.sat")];const [theme,setTheme]=useState("light");const [logoUrl,setLogoUrl]=useState(value.logoUrl);const timezones=["UTC","Europe/London","Europe/Berlin","Europe/Paris","Europe/Moscow","Asia/Qyzylorda","Asia/Almaty","Asia/Tashkent","Asia/Dubai","Asia/Tbilisi","Asia/Yerevan","Asia/Baku","Asia/Bishkek","Asia/Tokyo","Asia/Shanghai","Asia/Singapore","America/New_York","America/Chicago","America/Denver","America/Los_Angeles"];
 const applyTheme=(next:string)=>{setTheme(next);const resolved=next==="system"?(window.matchMedia("(prefers-color-scheme: dark)").matches?"dark":"light"):next;document.documentElement.dataset.theme=resolved};
 useEffect(()=>{fetch("/api/settings").then(r=>r.json()).then(body=>applyTheme(body.settings?.theme??"light"))},[]);
 const chooseLogo=(event:ChangeEvent<HTMLInputElement>)=>{const file=event.target.files?.[0];if(!file)return;if(!file.type.startsWith("image/")||file.size>1_500_000){notify(locale==="ru"?"Выберите изображение размером до 1,5 МБ":"Choose an image up to 1.5 MB");return}const reader=new FileReader();reader.onload=()=>setLogoUrl(String(reader.result));reader.readAsDataURL(file)};
 const save=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=new FormData(e.currentTarget);const raw=Object.fromEntries(form);const payload={name:raw.name,logoUrl,locale:raw.locale,timezone:raw.timezone,theme:raw.theme,dataRetentionDays:Number(raw.dataRetentionDays),analyticsEnabled:raw.analyticsEnabled==="on",aiTrainingOptIn:raw.aiTrainingOptIn==="on",workingHours:{days:form.getAll("workingDays").map(Number),start:String(raw.workingStart),end:String(raw.workingEnd)}};const response=await sendJson("/api/settings","PATCH",payload);if(response.ok){applyTheme(String(raw.theme));notify(t("settings.saved"));refresh()}else notify(t("settings.saveFailed"))};
 return <div className="settingsLayout"><form className="settingsCard" onSubmit={save}><h2>{t("settings.companyData")}</h2><label>{t("settings.companyName")}<input name="name" defaultValue={workspaceName} required/></label><label>{t("settings.companyLogo")}<div className="logoUploader">{logoUrl?<img src={logoUrl} alt="Company logo"/>:<span><ImageIcon size={22}/></span>}<label className="fileButton"><Upload size={16}/>{locale==="ru"?"Выбрать логотип":"Choose logo"}<input type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" onChange={chooseLogo}/></label>{logoUrl&&<button type="button" onClick={()=>setLogoUrl("")}>{locale==="ru"?"Удалить":"Remove"}</button>}</div></label><div className="formRow"><label>{t("settings.language")}<select name="locale" defaultValue={value.locale}><option value="ru">{t("language.ru")}</option><option value="en">{t("language.en")}</option></select></label><label>{t("settings.theme")}<select name="theme" value={theme} onChange={event=>applyTheme(event.target.value)}><option value="system">{t("settings.themeSystem")}</option><option value="light">{t("settings.themeLight")}</option><option value="dark">{t("settings.themeDark")}</option></select></label></div><label>{t("settings.timezone")}<select name="timezone" defaultValue={value.timezone}>{!timezones.includes(value.timezone)&&<option value={value.timezone}>{value.timezone}</option>}{timezones.map(zone=><option key={zone} value={zone}>{zone.replaceAll("_"," ")}</option>)}</select></label><fieldset><legend>{t("settings.workingDays")}</legend><div className="weekdayGrid">{weekdays.map((day,index)=><label key={index}><input type="checkbox" name="workingDays" value={index} defaultChecked={value.workingHours.days.includes(index)}/><span>{day}</span></label>)}</div></fieldset><div className="formRow"><label>{t("settings.workStart")}<input type="time" name="workingStart" defaultValue={value.workingHours.start} required/></label><label>{t("settings.workEnd")}<input type="time" name="workingEnd" defaultValue={value.workingHours.end} required/></label></div><label>{t("settings.retention")}<select name="dataRetentionDays" defaultValue={value.dataRetentionDays}><option value="90">{t("settings.days90")}</option><option value="365">{t("settings.year1")}</option><option value="1095">{t("settings.years3")}</option><option value="3650">{t("settings.years10")}</option></select></label><label className="checkRow"><input type="checkbox" name="analyticsEnabled" defaultChecked={value.analyticsEnabled}/><span><b>{t("settings.analytics")}</b><small>{t("settings.analyticsCopy")}</small></span></label><label className="checkRow"><input type="checkbox" name="aiTrainingOptIn" defaultChecked={value.aiTrainingOptIn}/><span><b>{t("settings.training")}</b><small>{t("settings.trainingCopy")}</small></span></label><button className="primary">{t("settings.save")}</button></form><section className="settingsCard"><h2>{t("settings.dataManagement")}</h2><p>{t("settings.exportCopy")}</p><a className="exportButton" href="/api/settings/export">{t("settings.export")}</a><div className="dangerZone"><b>{t("settings.deleteWorkspace")}</b><p>{t("settings.deleteCopy")}</p><small>{t("settings.deleteHint")}</small></div></section></div>
}
function NotificationsView({locale,rows,notify,refresh}:{locale:string;rows:PlatformData["notifications"];notify:(value:string)=>void;refresh:()=>void}){const t=createTranslator(locale);const mark=async()=>{const response=await fetch("/api/notifications",{method:"PATCH"});if(response.ok)refresh();else notify(t("notifications.markFailed"))};return <section className="dataSection"><div className="dataToolbar"><b>{t("notifications.unread",{count:rows.filter(r=>!r.readAt).length})}</b><button disabled={!rows.some(row=>!row.readAt)} onClick={mark}>{t("notifications.markAll")}</button></div>{rows.length?<div className="notificationList">{rows.map(row=><div className={row.readAt?"read":""} key={row.id}><span><Bell size={16}/></span><div><b>{row.title}</b><p>{row.body}</p></div><time>{new Date(row.createdAt).toLocaleString(dateLocale(locale))}</time></div>)}</div>:<Empty icon={Bell} title={t("notifications.empty")} copy={t("notifications.emptyCopy")}/>}</section>}

function AutomationsView({locale,rows,actions,notify,refresh}:{locale:string;rows:PlatformData["automations"];actions:PlatformData["actions"];notify:(v:string)=>void;refresh:()=>void}){const t=createTranslator(locale);const [open,setOpen]=useState(false);const triggerLabel=(value:string)=>value==="HANDOFF_CREATED"?t("trigger.handoff"):value==="AI_RESPONSE"?t("trigger.aiResponse"):value==="MESSAGE_RECEIVED"?t("trigger.messageReceived"):value.replaceAll("_"," ");const create=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const raw=Object.fromEntries(new FormData(e.currentTarget));let input:Record<string,unknown>;try{input=JSON.parse(String(raw.input||"{}"))}catch{notify(t("automations.invalidJson"));return}const response=await sendJson("/api/automations","POST",{name:raw.name,trigger:raw.trigger,conditions:{},steps:[{actionKey:raw.actionKey,input}],enabled:false});if(response.ok){setOpen(false);notify(t("automations.created"));refresh()}else notify(t("automations.createFailed"))};const toggle=async(id:string,enabled:boolean)=>{const response=await sendJson(`/api/automations/${id}`,"PATCH",{enabled});if(response.ok){notify(enabled?t("automations.enabled"):t("automations.disabled"));refresh()}else notify(t("automations.updateFailed"))};const remove=async(id:string)=>{if(!confirm(t("automations.confirmDelete")))return;const response=await fetch(`/api/automations/${id}`,{method:"DELETE"});if(response.ok)refresh();else notify(t("automations.deleteFailed"))};return <section className="dataSection"><div className="dataToolbar"><div><b>{t("automations.count",{count:rows.length})}</b><small>{t("automations.permissionNote")}</small></div><button className="primary miniPrimary" disabled={!actions.length} onClick={()=>setOpen(!open)}><Plus size={15}/>{t("automations.new")}</button></div>{open&&actions.length>0&&<form className="inlineForm stacked" onSubmit={create}><div className="formRow"><label>{t("automations.name")}<input name="name" required placeholder={t("automations.namePlaceholder")}/></label><label>{t("automations.when")}<select name="trigger"><option value="HANDOFF_CREATED">{t("trigger.handoff")}</option><option value="AI_RESPONSE">{t("trigger.aiResponse")}</option><option value="MESSAGE_RECEIVED">{t("trigger.messageReceived")}</option></select></label></div><div className="formRow"><label>{t("automations.action")}<select name="actionKey" required>{actions.map(a=><option key={a.key} value={a.key}>{a.name}</option>)}</select></label><label>{t("automations.parameters")}<input name="input" defaultValue='{"title":"Help needed","body":"Review the new conversation"}'/></label></div><button className="primary">{t("automations.createDisabled")}</button></form>}{rows.length?<div className="automationList">{rows.map(row=><div key={row.id}><span className="permissionIcon"><Zap size={17}/></span><div><b>{row.name}</b><p>{triggerLabel(row.trigger)} · {row.steps.map(s=>s.actionKey).join(", ")}</p></div><button role="switch" aria-checked={row.enabled} className={row.enabled?"switch on":"switch"} onClick={()=>toggle(row.id,!row.enabled)}><i/></button><button className="removeAutomation" onClick={()=>remove(row.id)}>{t("automations.delete")}</button></div>)}</div>:<Empty icon={Zap} title={t("automations.empty")} copy={t("automations.emptyCopy")}/>}</section>}

function Playground({locale,employeeId,notify}:{locale:string;employeeId:string;notify:(value:string)=>void}){const t=createTranslator(locale);const [messages,setMessages]=useState<Array<{role:"user"|"assistant";text:string}>>([]);const [busy,setBusy]=useState(false);const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!employeeId){notify(t("playground.noEmployee"));return}const form=e.currentTarget;const input=new FormData(form).get("message")?.toString().trim();if(!input)return;setMessages(v=>[...v,{role:"user",text:input}]);form.reset();setBusy(true);try{const response=await sendJson(`/api/widget/${employeeId}/messages`,"POST",{visitorId:`playground-${employeeId}`,messageId:crypto.randomUUID(),name:t("playground.customer"),message:input});const body=await response.json();setMessages(v=>[...v,{role:"assistant",text:response.ok?body.message:t("playground.failedReply")}]);if(!response.ok)notify(t("playground.sendFailed"))}catch{setMessages(v=>[...v,{role:"assistant",text:t("playground.failedReply")}]);notify(t("playground.sendFailed"))}finally{setBusy(false)}};return <section className="playground"><div className="messageStream">{messages.length?messages.map((m,i)=><div key={i} className={m.role==="user"?"bubble inbound":"bubble outbound"}><p>{m.text}</p></div>):<Empty icon={TestTube2} title={employeeId?t("playground.empty"):t("playground.noEmployee")} copy={t("playground.emptyCopy")}/>}</div><form onSubmit={submit}><input name="message" placeholder={t("playground.placeholder")} disabled={!employeeId||busy} required/><button aria-label={t("testing.run")} className="primary" disabled={!employeeId||busy}><Send size={16}/></button></form></section>}

function KnowledgeManager({locale,rows,notify,refresh}:{locale:string;rows:PlatformData["sources"];notify:(value:string)=>void;refresh:()=>void}){
  const t=createTranslator(locale);const [kind,setKind]=useState<"TEXT"|"FAQ"|"WEBSITE"|"DOCUMENT">("TEXT");
  const kindLabel=(type:string)=>type==="TEXT"?t("knowledge.text"):type==="FAQ"?"FAQ":type==="WEBSITE"?t("knowledge.website"):t("knowledge.document");
  const statusLabel=(status:string)=>status==="READY"?t("knowledge.ready"):status==="FAILED"?t("knowledge.error"):t("knowledge.processing");
  const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=e.currentTarget;const values=Object.fromEntries(new FormData(form));let response:Response;if(kind==="DOCUMENT")response=await fetch("/api/knowledge/documents",{method:"POST",body:new FormData(form)});else response=await sendJson("/api/knowledge","POST",{type:kind,title:values.title,content:values.content,uri:values.uri});const body=await response.json();if(response.ok){form.reset();notify(t("knowledge.accepted"));refresh()}else notify(typeof body.error==="string"&&body.error?t("knowledge.failed"):t("knowledge.failed"))};
  return <div className="stackedPage"><KnowledgeHealth locale={locale}/><section className="dataSection"><div className="dataToolbar"><div><b>{t("knowledge.count",{count:rows.length})}</b><small>{t("knowledge.privacy")}</small></div><div className="knowledgeKinds">{(["TEXT","FAQ","WEBSITE","DOCUMENT"] as const).map(type=><button type="button" className={kind===type?"primary":""} key={type} onClick={()=>setKind(type)}>{kindLabel(type)}</button>)}</div></div><form className="inlineForm stacked" onSubmit={submit}>{kind==="DOCUMENT"?<label className="fileDrop">{t("knowledge.fileHint")}<input name="file" type="file" accept=".pdf,.docx,.txt,.csv,.xlsx" required/></label>:<><label>{t("knowledge.title")}<input name="title" required placeholder={kind==="WEBSITE"?t("knowledge.companySite"):t("knowledge.servicesPrices")}/></label>{kind==="WEBSITE"?<label>{t("knowledge.siteAddress")}<input name="uri" type="url" required placeholder="https://example.com"/></label>:kind==="FAQ"?<label>{t("knowledge.faq")}<textarea name="content" required minLength={10} placeholder={t("knowledge.faqPlaceholder")}/></label>:<label>{t("knowledge.information")}<textarea name="content" required minLength={10} placeholder={t("knowledge.infoPlaceholder")}/></label>}</>}<button className="primary">{t("knowledge.process")}</button></form>{rows.length?<div className="tableWrap"><table><thead><tr><th>{t("knowledge.source")}</th><th>{t("knowledge.type")}</th><th>{t("knowledge.documents")}</th><th>{t("knowledge.state")}</th></tr></thead><tbody>{rows.map(row=><tr key={row.id}><td><span className="tableTitle"><FileText size={16}/>{row.title}</span></td><td>{kindLabel(row.type)}</td><td>{row.documents}</td><td><span className={`status ${row.status==="READY"?"success":"paused"}`}>{statusLabel(row.status)}</span></td></tr>)}</tbody></table></div>:<Empty icon={BookOpen} title={t("knowledge.empty")} copy={t("knowledge.emptyCopy")}/>}</section></div>
}

type IntegrationRow={id:string;provider:string;status:string;lastSyncAt:string|null;lastError:string|null};
function IntegrationsView({locale,notify}:{locale:string;notify:(value:string)=>void}){const t=createTranslator(locale);const [rows,setRows]=useState<IntegrationRow[]>([]);const [open,setOpen]=useState(false);const load=()=>fetch("/api/integrations").then(r=>r.json()).then(value=>setRows(Array.isArray(value)?value:[]));useEffect(()=>{void load()},[]);const statusLabel=(value:string)=>value==="CONNECTED"?t("status.connected"):value==="ERROR"?t("status.error"):t("status.pending");const save=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=e.currentTarget;const response=await sendJson("/api/integrations","POST",Object.fromEntries(new FormData(form)));if(response.ok){setOpen(false);form.reset();notify(t("integrations.saved"));await load()}else notify(t("integrations.saveFailed"))};const test=async(id:string)=>{const response=await fetch(`/api/integrations/${id}/test`,{method:"POST"});notify(response.ok?t("integrations.connected"):t("integrations.testFailed"));await load()};const remove=async(id:string)=>{const response=await fetch(`/api/integrations/${id}`,{method:"DELETE"});if(!response.ok)notify(t("integrations.deleteFailed"));await load()};return <section className="dataSection"><div className="dataToolbar"><div><b>{t("integrations.title")}</b><small>{t("integrations.subtitle")}</small></div><button className="primary miniPrimary" onClick={()=>setOpen(!open)}><Plus size={15}/>{t("integrations.webhook")}</button></div>{open&&<form className="inlineForm stacked" onSubmit={save}><label>{t("integrations.endpoint")}<input name="endpoint" type="url" required placeholder="https://crm.example.com/webhooks/lemiri"/></label><label>Signing secret<input name="signingSecret" type="password" autoComplete="off" minLength={24} required/></label><label>{t("integrations.authorization")}<input name="authorization" type="password" autoComplete="off" placeholder="Bearer …"/></label><button className="primary">{t("integrations.save")}</button></form>}<div className="connectorGrid">{rows.map(row=><article className="connectorCard" key={row.id}><div className="connectorLogo"><WandSparkles size={20}/></div><div><h3>{t("integrations.webhook")}</h3><p>{row.lastSyncAt?t("integrations.lastSync",{date:new Date(row.lastSyncAt).toLocaleString(dateLocale(locale))}):t("integrations.awaitingTest")}</p>{row.lastError&&<small className="connectorError">{row.lastError}</small>}</div><span className={`status ${row.status==="CONNECTED"?"success":"paused"}`}>{statusLabel(row.status)}</span><div className="integrationActions"><button onClick={()=>test(row.id)}>{t("integrations.test")}</button><button onClick={()=>remove(row.id)}>{t("integrations.delete")}</button></div></article>)}</div>{!rows.length&&!open&&<Empty icon={WandSparkles} title={t("integrations.empty")} copy={t("integrations.emptyCopy")}/>}</section>}

type TestCaseRow={id:string;name:string;customerMessage:string;expectedContains:string|null;expectedHandoff:boolean|null;lastStatus:string|null;lastResponse:string|null;lastConfidence:number|null};
function TestLab({locale,employeeId,notify}:{locale:string;employeeId:string;notify:(value:string)=>void}){const t=createTranslator(locale);const [cases,setCases]=useState<TestCaseRow[]>([]);const [loading,setLoading]=useState(true);const [loadFailed,setLoadFailed]=useState(false);const [running,setRunning]=useState<string>();const load=async()=>{try{const response=await fetch("/api/test-cases");if(!response.ok)throw new Error("TEST_CASES_LOAD_FAILED");const value=await response.json();setCases(Array.isArray(value)?value:[]);setLoadFailed(false)}catch{setLoadFailed(true)}finally{setLoading(false)}};useEffect(()=>{void load()},[]);const create=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!employeeId){notify(t("playground.noEmployee"));return}const form=e.currentTarget;const v=Object.fromEntries(new FormData(form));const response=await sendJson("/api/test-cases","POST",{employeeId,name:v.name,customerMessage:v.customerMessage,expectedContains:String(v.expectedContains??"")||undefined,expectedHandoff:v.expectedHandoff==="true"?true:v.expectedHandoff==="false"?false:undefined});if(response.ok){form.reset();await load()}else notify(t("testing.createFailed"))};const run=async(id:string)=>{setRunning(id);try{const response=await fetch(`/api/test-cases/${id}/run`,{method:"POST"});if(!response.ok)notify(t("testing.runFailed"));await load()}finally{setRunning(undefined)}};const remove=async(id:string)=>{const response=await fetch(`/api/test-cases/${id}`,{method:"DELETE"});if(!response.ok)notify(t("testing.deleteFailed"));await load()};const status=(value:string|null)=>value==="PASSED"?t("testing.passed"):value==="FAILED"?t("testing.failed"):value??t("testing.notRun");return <div className="testLab"><Playground locale={locale} employeeId={employeeId} notify={notify}/><section className="dataSection"><div className="dataToolbar"><div><b>{t("testing.title")}</b><small>{t("testing.subtitle")}</small></div></div><form className="inlineForm stacked" onSubmit={create}><div className="formRow"><label>{t("testing.name")}<input name="name" disabled={!employeeId} required placeholder={t("testing.namePlaceholder")}/></label><label>{t("testing.expectedHandoff")}<select name="expectedHandoff" disabled={!employeeId}><option value="">{t("testing.doNotCheck")}</option><option value="false">{t("testing.no")}</option><option value="true">{t("testing.yes")}</option></select></label></div><label>{t("testing.customerMessage")}<textarea name="customerMessage" disabled={!employeeId} required/></label><label>{t("testing.expectedContains")}<input name="expectedContains" disabled={!employeeId} placeholder={t("testing.expectedPlaceholder")}/></label><button className="primary" disabled={!employeeId}>{t("testing.save")}</button></form>{loading?<div className="emptyState">{t("testing.loading")}</div>:loadFailed?<Empty icon={TestTube2} title={t("testing.loadFailed")} copy={t("testing.emptyCopy")}/>:cases.length?<div className="testCaseList">{cases.map(item=><article key={item.id}><div><b>{item.name}</b><p>{item.customerMessage}</p>{item.lastResponse&&<small>{item.lastResponse}</small>}</div><span className={`status ${item.lastStatus==="PASSED"?"success":"paused"}`}>{status(item.lastStatus)}</span><button disabled={running===item.id} onClick={()=>run(item.id)}>{running===item.id?t("testing.checking"):t("testing.run")}</button><button onClick={()=>remove(item.id)}>{t("testing.delete")}</button></article>)}</div>:<Empty icon={TestTube2} title={t("testing.empty")} copy={t("testing.emptyCopy")}/>}</section></div>}

function Empty({icon:Icon,title,copy}:{icon:typeof Settings;title:string;copy:string}){return <div className="emptyState"><span><Icon size={22}/></span><h3>{title}</h3><p>{copy}</p></div>}
